import { timingSafeEqual } from 'node:crypto';
import { Server } from 'node:net';

type EngineServerOptions = {
  port: number;
  hostname: string;
  fetch: (request: Request, server: unknown) => Response | Promise<Response>;
};

declare const Bun: { serve: (options: EngineServerOptions) => unknown };

const LOOPBACK_HOST = '127.0.0.1';
const MINIMUM_TOKEN_LENGTH = 32;
const token = process.env.RIVET_MEMORY_ACCESS_TOKEN;
const port = Number(process.env.SUPERMEMORY_PORT);

if (
  !token ||
  token.length < MINIMUM_TOKEN_LENGTH ||
  !Number.isInteger(port) ||
  port <= 0
) {
  throw new Error('Engine access configuration is missing or invalid');
}

const expectedAuthorization = Buffer.from(`Bearer ${token}`);
const serve = Bun.serve.bind(Bun);

Server.prototype.listen = new Proxy(Server.prototype.listen, {
  apply: (target, receiver, args: unknown[]) => {
    const isEnginePortCheck = args[0] === port && args[1] === '0.0.0.0';
    const parameters = isEnginePortCheck
      ? [args[0], LOOPBACK_HOST, ...args.slice(2)]
      : args;
    return Reflect.apply(target, receiver, parameters);
  },
});

Bun.serve = (options) => {
  if (options.port !== port || typeof options.fetch !== 'function') {
    throw new Error('Unexpected engine HTTP server configuration');
  }
  return serve({
    ...options,
    hostname: LOOPBACK_HOST,
    fetch: (request, server) => {
      const authorization = Buffer.from(
        request.headers.get('authorization') ?? '',
      );
      const isAuthorized =
        authorization.length === expectedAuthorization.length &&
        timingSafeEqual(authorization, expectedAuthorization);
      if (!isAuthorized) {
        return Response.json(
          {
            error: {
              code: 'AUTH_REQUIRED',
              message: 'Engine authentication required',
            },
          },
          { status: 401, headers: { 'Cache-Control': 'no-store' } },
        );
      }
      return options.fetch(request, server);
    },
  });
};

const ownerPid = process.ppid;
const OWNER_CHECK_INTERVAL_MS = 2_000;
setInterval(() => {
  if (process.ppid !== ownerPid) process.exit(0);
}, OWNER_CHECK_INTERVAL_MS).unref();
